using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "IncorruptibleEffect", menuName = "Data/Battle/Effects/Incorruptible Effect")]
public class IncorruptibleEffect : Effect
{
	public override string GetEffectDescription(int amount, GameObject effectOwner = null)
	{
		return Smart.Format(GetLocalizedDescription(), base.localizationManager.GetLocalizedUntilStartOfYourNextTurn()) + AppendedDescription();
	}
}
